"""Read-only catalog for PDFs generated by the climate-reporting service.

The website never creates reports and never writes to MongoDB.  It reads the
pipeline manifests mounted at ``/data`` and exposes only PDFs referenced by a
completed manifest.
"""

from __future__ import annotations

import json
import os
from datetime import datetime
from pathlib import Path
from typing import Any, Iterable


REPORT_KINDS = {"daily", "weekly", "monthly"}
KIND_LABELS = {"daily": "Diario", "weekly": "Semanal", "monthly": "Mensual"}


def data_root() -> Path:
    """Return the read-only pipeline mount, configurable for local testing."""

    return Path(os.environ.get("CLIMATE_REPORTING_DATA_ROOT", "/data")).resolve()


def _safe_pdf_path(root: Path, value: Any) -> Path | None:
    if not isinstance(value, str) or not value.lower().endswith(".pdf"):
        return None
    candidate = Path(value)
    if not candidate.is_absolute():
        candidate = root / candidate
    try:
        resolved = candidate.resolve(strict=True)
        resolved.relative_to(root)
    except (FileNotFoundError, OSError, ValueError):
        return None
    return resolved


def _timestamp(value: Any) -> int | None:
    if not isinstance(value, str):
        return None
    try:
        return int(datetime.fromisoformat(value.replace("Z", "+00:00")).timestamp())
    except (TypeError, ValueError, OverflowError):
        return None


def _manifest_records(manifest_path: Path, root: Path) -> Iterable[dict[str, Any]]:
    try:
        payload = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError):
        return
    if not isinstance(payload, dict):
        return
    if payload.get("status") != "complete":
        return
    kind = payload.get("kind")
    report_date = payload.get("report_date")
    if kind not in REPORT_KINDS or not isinstance(report_date, str):
        return

    window = payload.get("window") or {}
    in_date = _timestamp(window.get("start_utc"))
    out_date = _timestamp(window.get("end_utc"))
    result = ((payload.get("stages") or {}).get("pdf") or {}).get("result") or []
    for item in result:
        if not isinstance(item, dict) or item.get("generated") is not True:
            continue
        site = item.get("site")
        pdf_path = _safe_pdf_path(root, item.get("path"))
        if not isinstance(site, str) or not site or pdf_path is None:
            continue
        relative = pdf_path.relative_to(root).as_posix()
        yield {
            "site": site,
            "data-field": site,
            "zone": "",
            "name": f"{kind}-{report_date}",
            "kind": kind,
            "tipo": KIND_LABELS[kind],
            "report_date": report_date,
            "in-date": in_date,
            "out-date": out_date,
            "in_date": window.get("start_utc", ""),
            "out_date": window.get("end_utc", ""),
            "relative_path": relative,
            "path": str(pdf_path),
        }


def list_reports(authorized_sites: Iterable[str] | None = None) -> list[dict[str, Any]]:
    """List generated PDFs for the user's authorized sites.

    ``authorized_sites`` is normally ``session['fieldsChillHours'].keys()``.
    ``None`` is useful only for administrative/local inspection.
    """

    root = data_root()
    allowed = set(authorized_sites) if authorized_sites is not None else None
    records: list[dict[str, Any]] = []
    runs_root = root / "runs"
    if not runs_root.is_dir():
        return records
    for manifest_path in runs_root.glob("*/[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]/manifest.json"):
        for record in _manifest_records(manifest_path, root):
            if allowed is None or record["site"] in allowed:
                records.append(record)
    records.sort(key=lambda item: (item["report_date"], item["kind"], item["site"]), reverse=True)
    return records


def resolve_relative_pdf(relative_path: str) -> Path | None:
    """Resolve a catalog-relative path and enforce the mounted-root boundary."""

    if not isinstance(relative_path, str):
        return None
    root = data_root()
    try:
        candidate = (root / relative_path).resolve(strict=True)
        candidate.relative_to(root)
    except (FileNotFoundError, OSError, ValueError):
        return None
    if candidate.suffix.lower() != ".pdf":
        return None
    return candidate
